const WEEK1_JS = "const app=document.querySelector('#app'), prog=document.querySelector('#progress'), creditEl=document.querySelector('#credits');\nlet credits=0; const awarded=new Set(); let currentClock=''; let goalsComplete=true; let goalCredit=0;\nfunction setClock(t){currentClock=t;}\nfunction updateCredits(){if(creditEl) creditEl.textContent=`CREDITS ${credits} / 100`;}\nfunction award(key,n){if(!awarded.has(key)){awarded.add(key);credits=Math.min(100,credits+n);updateCredits();return `<div class=\\\"creditpop\\\">+${n} CREDITS</div>`}return '';}\nfunction resetCredits(){credits=0;awarded.clear();updateCredits();}\nconst panel=html=>{app.innerHTML=`<section class=\"panel\">${currentClock?`<div class=\"eyebrow globalclock\">${currentClock}</div>`:''}${html}</section>`;scrollTo({top:0,behavior:'smooth'})};\nconst setP=(n,label='')=>prog.textContent=n?`Station ${n} / 7${label?' · '+label:''}`:'Start';\nconst msg=(t,g=false)=>`<div class=\"notice ${g?'good':'bad'}\">${t}</div>`;\nconst meter=(n,label)=>`<div class=\"statusline\"><b>${label}</b><span>${n} %</span></div><div class=\"bar\"><i style=\"width:${n}%\"></i></div>`;\nconst anf327=()=>`<div class=\"req stickyreq\"><b>ANF-327 – Persönliches Überweisungslimit</b><br>0–1.000 € einschließlich: ohne zusätzliche Freigabe<br>&gt;1.000–10.000 € einschließlich: zusätzliche Freigabe erforderlich<br>&gt;10.000 €: unzulässig<br>Negative Werte: unzulässig<br>Nur ganze Eurobeträge.</div>`;\nlet picks=new Set();\nfunction start(){currentClock='';resetCredits();goalsComplete=true;goalCredit=0;setP(0);panel(`<div class=\"eyebrow\">Test-Rescue-Game</div><h1>Release 2.0</h1><h2>Release in Gefahr</h2><div class=\"story\"><b>Montag, 08:12 Uhr.</b><br><br>In zwei Wochen soll das neue Release des Kundenportals unseres Finanzinstituts live gehen. Aber in unserem Release-Projekt haben sich einige Fehler eingeschlichen und so können wir nicht live gehen.<br><br><b>Die Aufgabe:</b> Zuerst müssen die Vorbereitungen für die Testdurchführung abgeschlossen werden. Dabei sind die aufgetretenen Probleme zu lösen und Release 2.0 wieder auf Kurs zu bringen.<br><br>Dabei können auch unvorhergesehene Dinge passieren. Dann sind passende Lösungen gefragt.<br><br><b>Bereit für die Herausforderung?</b></div><button class=\"primary\" onclick=\"boot()\">Release retten</button>`)}\nfunction boot(){panel(`<div class=\"eyebrow\">Release 2.0</div><div class=\"story mono\">PROJEKTDATEN WERDEN GELADEN …<br><br><span class=\"badtext\">⚠ FEHLER BEIM LADEN</span><br><br>Testplanung für Release 2.0 unvollständig.<br><br><b>Der Auftrag – Testkonzept vervollständigen</b></div><button class=\"primary\" onclick=\"s1()\">Testkonzept öffnen</button>`)}\nfunction s1(){setP(1,'Woche 1 · Montag');panel(`<div class=\"eyebrow\">Station 1 · Montag 08:12 Uhr</div><h2>Der Auftrag – Testkonzept vervollständigen</h2>${meter(43,'STAND TESTKONZEPT')}<div class=\"file\"><b>TESTKONZEPT – RELEASE 2.0</b><br><br>Testobjekt: Kundenportal – Release 2.0 ✓<br>Testzeitraum: Vorbereitung Woche 1 · Durchführung und Abschluss Woche 2 ✓<br>Testziele: <span class=\"badtext\">DATEN BESCHÄDIGT</span><br>Testumfang: <span class=\"badtext\">DATEN BESCHÄDIGT</span><br>Testumgebung: <span class=\"badtext\">DATEI GELÖSCHT</span></div><button class=\"primary\" onclick=\"s1goals()\">Testziele prüfen</button>`)}\nfunction s1goals(){picks.clear();let a=[\n'Informationen über die Qualität von Release 2.0 gewinnen.',\n'Nachweisen, dass Release 2.0 vollständig fehlerfrei ist.',\n'Prüfen, ob festgelegte Anforderungen erfüllt sind.',\n'Fehlerzustände und Fehlerwirkungen aufdecken.',\n'Sicherstellen, dass nach Produktivsetzung niemals Fehlerwirkungen auftreten.',\n'Informationen als Grundlage für Entscheidungen bereitstellen.',\n'Alle gefundenen Fehlermeldungen müssen vor Testbeginn behoben sein.',\n'Jeder Testfall muss von zwei Personen ausgeführt werden.',\n'Die Testdurchführung darf ausschließlich positive Ergebnisse erzeugen.'\n];panel(`<div class=\"eyebrow\">Station 1 · Testziele</div><h2>Testziele vervollständigen</h2><div class=\"notice\">Mehrere Textfragmente gehören zum Testkonzept. Alle passenden Fragmente auswählen.</div><div class=\"options\">${a.map((x,i)=>`<button id=\"g${i}\" onclick=\"togglePick('g',${i})\">${String.fromCharCode(65+i)}) ${x}</button>`).join('')}</div><button onclick=\"checkGoals()\">Fragmente übernehmen</button><div id=\"fb\"></div>`)}\nfunction togglePick(prefix,i){let k=prefix+i;picks.has(k)?picks.delete(k):picks.add(k);document.querySelector('#'+k).classList.toggle('selected')}\nfunction checkGoals(){\n const right=[0,2,3,5], wrong=[1,4,6,7,8];\n const selectedRight=right.filter(i=>picks.has('g'+i)); const selectedWrong=wrong.filter(i=>picks.has('g'+i));\n if(!picks.size){document.querySelector('#fb').innerHTML=msg('Mindestens ein Fragment auswählen.');return;}\n if(selectedWrong.length){document.querySelector('#fb').innerHTML=msg('Mindestens ein ausgewähltes Fragment beschreibt kein geeignetes Testziel. Bitte die Auswahl korrigieren.');return;}\n if(!selectedRight.length){document.querySelector('#fb').innerHTML=msg('Noch kein passendes Testziel-Fragment ausgewählt. Bitte die Auswahl prüfen.');return;}\n goalCredit=selectedRight.length; goalsComplete=selectedRight.length===4;\n if(!awarded.has('goals')){awarded.add('goals');credits+=goalCredit;updateCredits();}\n const pct=goalsComplete?57:56;\n let goalNote=selectedRight.length===4?'<br><b>Alle passenden Testziel-Fragmente wurden erkannt.</b>':'<br><b>Es wurden noch nicht alle passenden Testziel-Fragmente gefunden.</b> Weitere passende Testziele hätten zusätzliche Credits ermöglicht.';\n document.querySelector('#fb').innerHTML=msg(`Auswahl übernommen. ${selectedRight.length} passende Testziel-Fragmente erkannt.${goalNote}`,true)+`<div class=\"creditpop\">+${goalCredit} CREDITS</div>`+meter(pct,'STAND TESTKONZEPT')+`<button class=\"primary\" onclick=\"s1scope()\">Testumfang prüfen</button>`;\n}\n\nfunction s1scope(){panel(`<div class=\"eyebrow\">Station 1 · Testumfang</div><h2>Testumfang klären</h2><div class=\"notice bad\"><b>Folgende Notiz wurde rekonstruiert. Kann diese so in das Testkonzept übernommen werden?</b><br><br>„Für Release 2.0 testen wir nur die neuen Funktionen. Bestehende Funktionen wurden schließlich bereits getestet.“</div><table><tr><th>Bereich</th><th>Änderung</th></tr><tr><td>Persönliches Überweisungslimit</td><td>NEU</td></tr><tr><td>Profilbild</td><td>NEU</td></tr><tr><td>Umsatzsuche</td><td>GEÄNDERT</td></tr><tr><td>Elektronisches Postfach</td><td>GEÄNDERT</td></tr><tr><td>Anmeldung / Kontosperre</td><td>TECHNISCH ÜBERARBEITET</td></tr><tr><td>Persönliche Daten</td><td>TECHNISCH ÜBERARBEITET</td></tr></table><button onclick=\"scope(false)\">Notiz übernehmen</button><button onclick=\"scope(true)\">Notiz als fehlerhaft markieren</button><div id=\"fb\"></div>`)}\nfunction scope(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ DATEN WURDEN KORRIGIERT',true)+award('scope',4)+`<div class=\"req\">Neue und geänderte Funktionen sowie bestehende Funktionen, die durch Änderungen betroffen sein können, müssen bei der Testplanung berücksichtigt werden.</div>${meter(71,'STAND TESTKONZEPT')}<button class=\"primary\" onclick=\"s1env()\">Testumgebung prüfen</button>`:msg('Die Änderungen können auch bestehende Funktionen beeinflussen.')}\nfunction s1env(){panel(`<div class=\"eyebrow\">Station 1 · Testumgebung</div><h2>Testumgebung festlegen</h2><div class=\"notice bad\">Es wurde keine Datei gefunden, aber es wurden drei mögliche Alternativen entdeckt. Welche passt zu Release 2.0?</div><div class=\"cards selectable-cards\"><button class=\"card choicecard\" onclick=\"env(false)\"><h4>Anwendungstestumgebung</h4>Release 2.0 bereitstellbar; häufige neue Zustände; nicht alle angebundenen Systeme release-nah.</button><button class=\"card choicecard\" onclick=\"env(true)\"><h4>Zentrale Testumgebung</h4>Vorgesehener Stand; benötigte Systeme/Schnittstellen; definierte Testkonten/-daten; kontrollierte Ausgangslage.</button><button class=\"card choicecard\" onclick=\"env(false)\"><h4>Entwicklungsumgebung</h4>Aktuelle Komponentenstände; kurzfristige Änderungen; nicht zwingend alle Komponenten gleichzeitig verfügbar.</button></div><div id=\"fb\"></div>`)}\nfunction env(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ DATEN WURDEN KORRIGIERT',true)+award('env',4)+meter(goalsComplete?100:99,'STAND TESTKONZEPT')+`<button class=\"primary\" onclick=\"s1end()\">Testkonzept abschließen</button>`:msg('Diese Umgebung erfüllt die aufgeführten Anforderungen nicht vollständig.')}\nfunction s1end(){let pct=goalsComplete?100:99;panel(`<div class=\"eyebrow\">Station 1 · Abschluss</div><h2>${pct===100?'TESTKONZEPT VOLLSTÄNDIG':'TESTKONZEPT FAST VOLLSTÄNDIG'}</h2>${meter(pct,'STAND TESTKONZEPT')}<div class=\"notice good\"><b>Testziele:</b> ${goalsComplete?'wurden vollständig wiederhergestellt':'wurden teilweise wiederhergestellt'}<br><b>Testumfang:</b> wurde repariert<br><b>Testumgebung:</b> wurde wiederhergestellt</div><div class=\"story mono\">ÄNDERUNGEN WERDEN GESPEICHERT …<br>TESTKONZEPT WIRD VALIDIERT …<br><span class=\"goodtext\">✓ ERFOLGREICH</span></div><button class=\"primary\" onclick=\"s1transition()\">Weiter</button>`)}\nfunction s1transition(){panel(`<div class=\"eyebrow\">Woche 1 – 17:58 Uhr</div><h2>Geschafft – das Testkonzept steht!</h2><div class=\"story\">Doch damit ist Release 2.0 noch lange nicht gerettet. Weitere Herausforderungen warten bereits.<br><br><b>Bereit, weiterzumachen?</b></div><button class=\"primary\" onclick=\"s2()\">Dienstag öffnen</button>`)}\nfunction s2(){setP(2,'Woche 1 · Dienstag');panel(`<div class=\"eyebrow\">Station 2 · Dienstag 08:47 Uhr</div><h2>Sind wir bereit für Woche 2?</h2><div class=\"story\"><b>VORBEREITUNG DER TESTDURCHFÜHRUNG</b><br><br>Das Testkonzept für Release 2.0 steht. Die Testdurchführung soll in der kommenden Woche beginnen. Vorher muss geprüft werden, ob die notwendigen Voraussetzungen dafür geschaffen sind.<br><br>Im Projekt wurden verschiedene Statusmeldungen gesammelt. Doch nicht alles ist bereits geklärt.</div><p><b>Welche Punkte müssen noch bearbeitet oder geklärt werden?</b></p><button class=\"primary\" onclick=\"s2status()\">Vorbereitung prüfen</button>`) }\nlet prepPicks=new Set();\n// Station 2: Drei Pflichtpunkte müssen erkannt werden. Zwei zusätzliche offene Punkte sind optional.\n// Werden optionale Punkte erkannt, bringen sie Zusatzcredits und erhalten auf der Folgeseite ebenfalls einen Maßnahmenblock.\nconst prepItems=[\n {text:'Testzeitraum für Woche 2 ist abgestimmt.',state:'ok'},\n {text:'Für einen wichtigen Geschäftsfall fehlen benötigte Testdaten. Davon ist nur ein Teil der geplanten Tests betroffen.',state:'optional'},\n {text:'Release 2.0 wurde auf der Zentralen Testumgebung noch nicht bestätigt.',state:'must'},\n {text:'Testwerkzeug steht für Woche 2 zur Verfügung.',state:'ok'},\n {text:'Eine für Release 2.0 vorgesehene Änderung ist fachlich noch nicht eindeutig beschrieben. Umfang und erforderliche Umsetzung sind noch ungeklärt.',state:'must'},\n {text:'Eine benötigte Schnittstelle steht noch nicht zur Verfügung. Davon sind nur wenige geplante Testfälle betroffen.',state:'optional'},\n {text:'Die Verfügbarkeit eines für Woche 2 benötigten Testers ist noch nicht bestätigt.',state:'must'},\n {text:'Die übrigen Anforderungen für Release 2.0 liegen in abgestimmter Form vor.',state:'ok'},\n {text:'Die für Woche 2 bereits bestätigten Tester haben Zugriff auf das Testwerkzeug.',state:'ok'},\n {text:'Die Ansprechpartner für fachliche Rückfragen in Woche 2 sind benannt.',state:'ok'}\n];\nlet selectedActionIndices=[];\nfunction s2status(){prepPicks.clear();selectedActionIndices=[];panel(`<div class=\"eyebrow\">Station 2 – Testvorbereitung</div><h2>Voraussetzungen prüfen</h2><div class=\"notice\">Die Vorbereitungen für die Testdurchführung laufen. Einige Voraussetzungen sind bereits erfüllt, bei anderen besteht noch Handlungsbedarf.<br><br><b>Welche Punkte müssen noch bearbeitet oder geklärt werden?</b><br><br>Mehrere Statusmeldungen können ausgewählt werden. Einige Punkte sind für den geplanten Start der Testdurchführung besonders wichtig. Andere betreffen nur einzelne Tests, können aber ebenfalls berücksichtigt werden.</div><div class=\"prepgrid\">${prepItems.map((x,i)=>`<button id=\"prep${i}\" class=\"prepitem\" onclick=\"togglePrep(${i})\">${x.text}</button>`).join('')}</div><button onclick=\"checkPrep()\">Auswahl prüfen</button><div id=\"fb\"></div>`) }\nfunction togglePrep(i){let k='prep'+i;prepPicks.has(i)?prepPicks.delete(i):prepPicks.add(i);document.querySelector('#'+k).classList.toggle('selected')}\nfunction checkPrep(){\n const selected=[...prepPicks];\n const selectedOk=selected.filter(i=>prepItems[i].state==='ok');\n const must=prepItems.map((x,i)=>x.state==='must'?i:null).filter(i=>i!==null);\n const missingMust=must.filter(i=>!prepPicks.has(i));\n const optional=prepItems.map((x,i)=>x.state==='optional'?i:null).filter(i=>i!==null);\n const selectedOptional=optional.filter(i=>prepPicks.has(i));\n if(!prepPicks.size){document.querySelector('#fb').innerHTML=msg('Mindestens einen Punkt auswählen.');return;}\n if(selectedOk.length){document.querySelector('#fb').innerHTML=msg('Mindestens ein ausgewählter Punkt ist bereits geklärt und stellt aktuell keinen Handlungsbedarf dar. Bitte die Auswahl prüfen.');return;}\n if(missingMust.length){const n=missingMust.length;const text=n===1?'Es fehlt noch eine Voraussetzung, die vor dem geplanten Testbeginn geklärt werden muss.':`Es fehlen noch ${n===2?'zwei':'drei'} Voraussetzungen, die vor dem geplanten Testbeginn geklärt werden müssen.`;document.querySelector('#fb').innerHTML=msg(text+' Bitte die Auswahl prüfen.');return;}\n selectedActionIndices=[4,2,6];\n if(prepPicks.has(1)) selectedActionIndices.push(1);\n if(prepPicks.has(5)) selectedActionIndices.push(5);\n let bonus='';\n if(!awarded.has('s2prep')){awarded.add('s2prep');credits+=3;updateCredits();bonus+=`<div class=\"creditpop\">+3 CREDITS</div>`;}\n selectedOptional.forEach(i=>{const key='s2optional'+i;if(!awarded.has(key)){awarded.add(key);credits+=1;updateCredits();bonus+=`<div class=\"creditpop\">+1 CREDIT · zusätzlicher Handlungsbedarf erkannt</div>`;}});\n let feedback;\n if(selectedOptional.length===0){feedback='Korrekt, es wurden die Voraussetzungen gewählt, die auf jeden Fall vorher noch geklärt werden müssen. Weitere Voraussetzungen hätten zusätzliche Credits ermöglicht, können aber auch noch in der Folgewoche geklärt werden.';}\n else if(selectedOptional.length===1){feedback='Korrekt, es wurden die Voraussetzungen gewählt, die auf jeden Fall vorher noch geklärt werden müssen. Zudem wurde eine von zwei weiteren Voraussetzungen gewählt, die zusätzliche Credits ergibt.';}\n else{feedback='Korrekt, es wurden die Voraussetzungen gewählt, die auf jeden Fall vorher noch geklärt werden müssen. Zudem wurden zwei weitere Voraussetzungen gewählt, die zusätzliche Credits ergeben.';}\n document.querySelector('#fb').innerHTML=msg(feedback,true)+bonus+`<button class=\"primary\" onclick=\"s2actions()\">Maßnahmen ableiten</button>`;\n document.querySelectorAll('.prepitem').forEach(b=>b.disabled=true);\n}\nconst actionSets={\n 4:{title:'Änderung fachlich noch nicht eindeutig beschrieben',correct:1,opts:[\n  'Die vorhandene Beschreibung zunächst als Arbeitsgrundlage verwenden, die Testanalyse fortsetzen und offene fachliche Punkte erst bei der Testdurchführung klären.',\n  'Fachliche Klärung mit den zuständigen Ansprechpartnern veranlassen, Auswirkungen auf Umfang und Umsetzung bewerten und die Testplanung bei Bedarf anpassen.',\n  'Die Änderung vorläufig aus dem Testumfang nehmen und erst nach Abschluss der übrigen Tests entscheiden, ob sie für Release 2.0 noch berücksichtigt wird.'\n ]},\n 2:{title:'Release 2.0 auf der Zentralen Testumgebung noch nicht bestätigt',correct:0,opts:[\n  'Status der vorgesehenen Releasekonfiguration klären, die Bereitstellung bis zum Testbeginn verfolgen und die erfolgreiche Installation bestätigen lassen.',\n  'Die Testdurchführung wie geplant vorbereiten und am ersten Testtag anhand der verfügbaren Funktionen feststellen, welcher Stand tatsächlich installiert ist.',\n  'Die bereits bestätigten Teile der Testumgebung als ausreichend bewerten und nur bei auftretenden Abweichungen den installierten Releasestand nachträglich prüfen.'\n ]},\n 6:{title:'Verfügbarkeit eines benötigten Testers noch nicht bestätigt',correct:1,opts:[\n  'Die bisherige Aufgabenverteilung beibehalten und die Verfügbarkeit unmittelbar vor Beginn der Testdurchführung erneut prüfen.',\n  'Verfügbarkeit verbindlich klären und prüfen, ob bei fehlender Kapazität die Ressourcen- oder Testplanung angepasst werden muss.',\n  'Die vorgesehenen Tests vorsorglich auf die bereits bestätigten Tester verteilen und die ursprüngliche Ressourcenplanung nur anpassen, falls später tatsächlich Kapazität fehlt.'\n ]},\n 1:{title:'Testdaten für einen wichtigen Geschäftsfall fehlen',correct:1,opts:[\n  'Die betroffenen Tests zunächst zurückstellen und erst im Verlauf von Woche 2 prüfen, ob die benötigten Testdaten inzwischen bereitstehen.',\n  'Betroffene Tests identifizieren, Bereitstellung der benötigten Testdaten veranlassen, den Status weiterverfolgen und andere durchführbare Tests wie geplant vorbereiten.',\n  'Die Bereitstellung der Testdaten vor Beginn der gesamten Testdurchführung abwarten, damit alle vorgesehenen Tests in der ursprünglich geplanten Reihenfolge durchgeführt werden können.'\n ]},\n 5:{title:'Benötigte Schnittstelle steht noch nicht zur Verfügung',correct:1,opts:[\n  'Die betroffenen Testfälle in der ursprünglichen Reihenfolge belassen und erst bei Erreichen dieser Tests entscheiden, ob eine Umplanung notwendig ist.',\n  'Betroffene Testfälle identifizieren, Verfügbarkeit der Schnittstelle weiterverfolgen und zunächst unabhängig davon durchführbare Tests einplanen.',\n  'Die betroffenen Testfälle bis zur Bereitstellung der Schnittstelle aus der aktuellen Planung herausnehmen und erst nach deren Verfügbarkeit wieder in den Testumfang aufnehmen.'\n ]}\n};\nlet actionPicks={};\nfunction s2actions(){actionPicks={};const sets=selectedActionIndices.map(i=>({itemIndex:i,...actionSets[i]}));panel(`<div class=\"eyebrow\">Station 2 – Testvorbereitung</div><h2>Maßnahmen festlegen</h2><div class=\"story\">Für jeden ausgewählten Handlungsbedarf ist eine passende Maßnahme festzulegen. Nicht jeder offene Punkt muss bereits vor Woche 2 vollständig erledigt sein. Entscheidend ist ein angemessener Umgang mit der jeweiligen Voraussetzung.</div><div class=\"actiongrid\">${sets.map(a=>`<div class=\"req\"><b>${a.title}</b><div class=\"measuretiles\" id=\"measure${a.itemIndex}\">${a.opts.map((o,j)=>`<button onclick=\"pickAction(${a.itemIndex},${j})\" id=\"measure${a.itemIndex}_${j}\">${o}</button>`).join('')}</div></div>`).join('')}</div><button onclick=\"checkActions()\">Maßnahmen prüfen</button><div id=\"fb\"></div>`) }\nfunction pickAction(group,opt){actionPicks[group]=opt;document.querySelectorAll(`#measure${group} button`).forEach(b=>b.classList.remove('selected'));document.querySelector(`#measure${group}_${opt}`).classList.add('selected')}\nfunction checkActions(){\n if(selectedActionIndices.some(i=>actionPicks[i]===undefined)){document.querySelector('#fb').innerHTML=msg('Für jeden angezeigten Handlungsbedarf eine Maßnahme auswählen.');return;}\n const wrong=selectedActionIndices.filter(i=>actionPicks[i]!==actionSets[i].correct).length;\n if(wrong){document.querySelector('#fb').innerHTML=msg('Mindestens eine Maßnahme ist noch nicht die angemessenste Reaktion auf den jeweiligen Handlungsbedarf. Die Entscheidungen können noch einmal geprüft und geändert werden.');return;}\n document.querySelectorAll('.measuretiles button').forEach(b=>b.disabled=true);\n const n=selectedActionIndices.length;\n document.querySelector('#fb').innerHTML=msg(`Passende Maßnahmen wurden für alle ${n} ausgewählten Handlungsbedarfe festgelegt.`,true)+award('s2actions',6)+`<button class=\"primary\" onclick=\"s2update()\">weiter</button>`;\n}\nfunction s2update(){\n const testdata=selectedActionIndices.includes(1)?'<br>• Die fehlenden Testdaten wurden angefordert. Die betroffenen Tests sind identifiziert und der Status wird weiterverfolgt.':'';\n const iface=selectedActionIndices.includes(5)?'<br>• Die betroffenen Testfälle zur noch nicht verfügbaren Schnittstelle sind identifiziert. Andere durchführbare Tests können zunächst stattfinden.':'';\n const optionalBlock=(testdata||iface)?`<div class=\"notice\"><b>Zusätzlich erkannte offene Punkte:</b>${testdata}${iface}</div>`:'';\n panel(`<div class=\"eyebrow\">Station 2 · Dienstag 16:36 Uhr</div><h2>Update zur Testvorbereitung</h2><div class=\"notice good\">✓ Die fachlich unklare Änderung wurde geklärt. Umfang und erforderliche Umsetzung sind abgestimmt; die Bereitstellung ist bis Freitag vorgesehen.<br>✓ Die Installation von Release 2.0 auf der Zentralen Testumgebung ist für Freitag eingeplant und wird anschließend bestätigt.<br>✓ Die Verfügbarkeit des benötigten Testers wurde bestätigt.</div>${optionalBlock}<div class=\"story\"><b>Wie ist der aktuelle Stand zu bewerten?</b><br><br>Die Testdurchführung beginnt erst in der kommenden Woche. Die für den geplanten Start wichtigen Voraussetzungen werden bis dahin geklärt. Erkannte weitere Einschränkungen werden für die jeweils betroffenen Tests weiterverfolgt.</div><div class=\"options\" id=\"assessmentOptions\"><button id=\"ass0\" onclick=\"s2assessment(false,0)\">Die Testdurchführung kann sofort beginnen.</button><button id=\"ass1\" onclick=\"s2assessment(true,1)\">Die Vorbereitung kann fortgesetzt werden. Die offenen Punkte müssen bis zum Testbeginn beziehungsweise für die jeweils betroffenen Tests weiterverfolgt werden.</button><button id=\"ass2\" onclick=\"s2assessment(false,2)\">Alle offenen Punkte können geschlossen werden, weil Maßnahmen geplant sind.</button><button id=\"ass3\" onclick=\"s2assessment(false,3)\">Die Testdurchführung muss bereits jetzt vollständig abgesagt werden.</button></div><div id=\"fb\"></div>`)\n}\nfunction s2assessment(ok,id){document.querySelectorAll('#assessmentOptions button').forEach(b=>b.classList.remove('selected'));document.querySelector('#ass'+id).classList.add('selected');document.querySelector('#fb').innerHTML=ok?msg('Korrekt. Die wichtigen Voraussetzungen werden bis zum Testbeginn geklärt. Erkannte weitere Einschränkungen werden für die jeweils betroffenen Tests weiterverfolgt.',true)+`<button class=\"primary\" onclick=\"s2end()\">Vorbereitung abschließen</button>`:msg('Bitte noch einmal prüfen: Geplante Maßnahmen und bekannte Einschränkungen sind noch nicht dasselbe wie bereits vollständig erfüllte Voraussetzungen.')}\nfunction s2end(){const extras=selectedActionIndices.length-3;panel(`<div class=\"eyebrow\">Station 2 · Abschluss</div><h2>TESTVORBEREITUNG SOWEIT ABGESCHLOSSEN</h2><div class=\"notice good\">✓ Drei wichtige Voraussetzungen identifiziert<br>✓ Passende Maßnahmen festgelegt<br>✓ Wichtige Voraussetzungen für Woche 2 werden geklärt${extras?`<br>✓ ${extras===2?'Zwei weitere offene Punkte wurden':'Ein weiterer offener Punkt wurde'} erkannt und für die betroffenen Tests berücksichtigt`:''}</div><button class=\"primary\" onclick=\"s2transition()\">Weiter</button>`) }\nfunction s2transition(){panel(`<div class=\"eyebrow\">Woche 1 – Dienstag 18:27 Uhr</div><h2>Geschafft – die Testvorbereitungen sind erfolgt!</h2><div class=\"story\">Die Vorbereitungen für die Woche 2 sind eingeleitet.<br><br>Währenddessen beginnt die konkrete Analyse der Anforderungen für Release 2.0. Als Nächstes wird Unterstützung bei der Testfallanalyse benötigt.<br><br><b>Kann es weitergehen?</b></div><button class=\"primary\" onclick=\"s3intro()\">Mittwoch öffnen</button>`) }\nfunction s3intro(){setP(3,'Woche 1 · Mittwoch');panel(`<div class=\"eyebrow\">Mittwoch · 09:18 Uhr</div><h2>Unterstützung bei der Testfallanalyse</h2><div class=\"story\">Die Tester sind dabei, die Anforderungen zu sichten und zu analysieren und daraus Testinhalte abzuleiten. Testfälle werden im Tool erstellt.<br><br>Ein Kollege benötigt dabei Unterstützung. Hier muss unter die Arme gegriffen werden.</div><button class=\"primary\" onclick=\"s3()\">Unterstützung beginnen</button>`)}\nfunction s3(){setP(3,'Woche 1 · Mittwoch');panel(`<div class=\"eyebrow\">Station 3 – Testfallanalyse</div><h2>Das neue Überweisungslimit</h2>${meter(0,'TESTFALLANALYSE UND -ERSTELLUNG')}${anf327()}<button class=\"primary\" onclick=\"s3classes()\">Anforderung analysieren</button>`)}\nfunction s3classes(){picks.clear();let vals=['−500','−1','0','1','500','999','1.000','1.001','5.000','9.999','10.000','10.001','15.000'];panel(`<div class=\"eyebrow\">Station 3 – Testfallanalyse</div><h2>Äquivalenzklassen</h2>${anf327()}<p>Wählt alle Werte der Klasse <b>„zusätzliche Freigabe erforderlich“ (&gt;1.000 bis 10.000 €)</b>.</p><div class=\"chips\">${vals.map((v,i)=>`<button class=\"chip\" id=\"v${i}\" onclick=\"togglePick('v',${i})\">${v} €</button>`).join('')}</div><button onclick=\"checkClass()\">Klasse prüfen</button><div id=\"fb\"></div>`)}\nfunction checkClass(){let right=[7,8,9,10],ok=right.every(i=>picks.has('v'+i))&&picks.size===4;document.querySelector('#fb').innerHTML=ok?msg('✓ ÄQUIVALENZKLASSE KORREKT',true)+award('s3class',5)+meter(35,'TESTFALLANALYSE UND -ERSTELLUNG')+`<button class=\"primary\" onclick=\"s3representatives()\">Vertreter auswählen</button>`:msg('Prüft noch einmal die Grenzen der Klasse in ANF-327.')}\nfunction s3representatives(){let all=`<option value=\"\" selected disabled>– Wert auswählen –</option><option value=\"−500\">−500</option><option value=\"−1\">−1</option><option value=\"0\">0</option><option value=\"1\">1</option><option value=\"500\">500</option><option value=\"999\">999</option><option value=\"1.000\">1.000</option><option value=\"1.001\">1.001</option><option value=\"5.000\">5.000</option><option value=\"9.999\">9.999</option><option value=\"10.000\">10.000</option><option value=\"10.001\">10.001</option><option value=\"15.000\">15.000</option>`;panel(`<div class=\"eyebrow\">Station 3 – Testfallanalyse</div><h2>Äquivalenzklassen</h2>${anf327()}<p>Für eine erste Abdeckung genügt jeweils ein repräsentativer Wert. Mehrere Lösungen sind möglich.</p><div class=\"grid4\">${['A &lt; 0 €','B 0–1.000 €','C &gt;1.000–10.000 €','D &gt;10.000 €'].map((x,i)=>`<div class=\"bucket\">${x}<br><select id=\"e${i+1}\" autocomplete=\"off\">${all}</select></div>`).join('')}</div><button onclick=\"checkRepresentatives()\">Vertreter übernehmen</button><div id=\"fb\"></div>`);['e1','e2','e3','e4'].forEach(id=>{const el=document.getElementById(id);if(el){el.selectedIndex=0;el.value='';}})}\nfunction checkRepresentatives(){let a=[e1.value,e2.value,e3.value,e4.value], ok=a[0]&&a[1]&&a[2]&&a[3]&&['−500','−1'].includes(a[0])&&['0','1','500','999','1.000'].includes(a[1])&&['1.001','5.000','9.999','10.000'].includes(a[2])&&['10.001','15.000'].includes(a[3]);document.querySelector('#fb').innerHTML=ok?msg('✓ Für jede Äquivalenzklasse wurde ein passender Vertreter gewählt.',true)+award('s3rep',5)+`<button class=\"primary\" onclick=\"s3thursday()\">Weiter</button>`:msg('Mindestens ein Wert gehört nicht zur gewählten Äquivalenzklasse.')}\nfunction s3thursday(){panel(`<div class=\"eyebrow\">Station 3 – Mittwoch 19:04 Uhr</div><div class=\"sleepcard\"><div class=\"sleepart\" aria-hidden=\"true\">🌙<br><span>😴</span> 🛏️</div><h2>Feierabend</h2><p>Für heute ist genug analysiert. Die restliche Testfallanalyse geht morgen weiter.</p><div class=\"mono\">… einige Stunden später …</div></div><button class=\"primary\" onclick=\"s3thursdayStart()\">Donnerstag starten</button>`)}\nfunction s3thursdayStart(){setP(3,'Woche 1 · Donnerstag');panel(`<div class=\"eyebrow\">Station 3 – Testfallanalyse</div><h2>Grenzwertanalyse</h2>${anf327()}<div class=\"story\">Die Äquivalenzklassen stehen. Jetzt werden die Grenzwertübergänge betrachtet.</div><button class=\"primary\" onclick=\"s3bounds()\">Grenzwerte prüfen</button>`)}\nfunction s3bounds(){panel(`<div class=\"eyebrow\">Station 3 – Testfallanalyse</div><h2>Grenzwertübergänge</h2>${anf327()}<p>An drei Stellen ändert sich das erwartete Verhalten. Welche drei Paare liegen direkt an diesen Grenzen?</p><div class=\"options\"><button id=\"b1\" onclick=\"bound(false,'b1')\">0/1 · 999/1.000 · 9.999/10.000</button><button id=\"b2\" onclick=\"bound(true,'b2')\">−1/0 · 1.000/1.001 · 10.000/10.001</button><button id=\"b3\" onclick=\"bound(false,'b3')\">−500/0 · 500/5.000 · 10.000/15.000</button></div><div id=\"fb\"></div>`)}\nfunction bound(ok,id){document.querySelectorAll('.options button').forEach(b=>b.classList.remove('selected'));document.querySelector('#'+id).classList.add('selected');document.querySelector('#fb').innerHTML=ok?msg('✓ GRENZWERTÜBERGÄNGE KORREKT',true)+award('s3bound',5)+meter(70,'TESTFALLANALYSE UND -ERSTELLUNG')+`<button class=\"primary\" onclick=\"s3data()\">Testfälle erstellen</button>`:msg('Diese Werte liegen nicht jeweils direkt auf beiden Seiten der drei relevanten Grenzen.')}\nfunction s3data(){panel(`<div class=\"eyebrow\">Station 3 – Testfallerstellung</div><h2>Testfälle erstellen</h2>${anf327()}<table><tr><th>Testfall</th><th>Wert</th><th>Erwartetes Ergebnis</th></tr><tr><td>TF-327-01</td><td>−1 €</td><td>Eingabe abgelehnt</td></tr><tr><td>TF-327-02</td><td>0 €</td><td>Keine zusätzliche Freigabe</td></tr><tr><td>TF-327-03</td><td>1.000 €</td><td>Keine zusätzliche Freigabe</td></tr><tr><td>TF-327-04</td><td>1.001 €</td><td>Zusätzliche Freigabe erforderlich</td></tr><tr><td>TF-327-05</td><td>10.000 €</td><td>Zusätzliche Freigabe erforderlich</td></tr><tr><td>TF-327-06</td><td>10.001 €</td><td>Eingabe abgelehnt</td></tr></table>${meter(100,'TESTFALLANALYSE UND -ERSTELLUNG')}<div class=\"notice good\">6 Testfälle wurden für das Thema Überweisungslimit erstellt. Weitere 234 wurden für die anderen Bereiche erstellt.<br><b>Status: Testanalyse und Testentwurf abgeschlossen.</b></div><button class=\"primary\" onclick=\"finishCases()\">Woche 1 abschließen</button>`)}\nfunction finishCases(){let bonus=award('s3cases',5);week1code(bonus)}\nfunction week1code(bonus=''){panel(`${bonus}<div class=\"eyebrow\">Station 3 – Abschluss</div><h2>Code gefunden</h2><div class=\"bigstatus center\">8306</div><div class=\"story center\"><b>Dieser Code wird später noch benötigt.</b><br>Am besten notieren.</div><button class=\"primary\" onclick=\"week1end()\">Woche 1 abschließen</button>`)}\nfunction week1end(bonus=''){setP(3,'Woche 1 · Freitag');panel(`${bonus}<div class=\"eyebrow\">Woche 1 – Freitag 16:42 Uhr</div><h2>BEREIT FÜR DIE TESTDURCHFÜHRUNG</h2><div class=\"notice good\"><b>Die Vorbereitungen für die kommende Woche sind abgeschlossen:</b><br><br>✓ Testplanung wurde wiederhergestellt<br>✓ Ressourcen für Woche 2 wurden bestätigt<br>✓ Release 2.0 steht auf der Zentralen Testumgebung bereit<br>✓ Testanalyse und Testfallerstellung sind abgeschlossen</div><div class=\"notice good\"><b>WOCHE 1 ABGESCHLOSSEN</b><br>Die Testdurchführung beginnt in Woche 2.</div><button class=\"primary\" onclick=\"if(parent&&typeof parent.openWeek2QS==='function'){parent.openWeek2QS()}else{parent.postMessage({type:'openWeek2'},'*')}\">Woche 2 starten</button>`)}\n\nstart();\n";
const WEEK2_JS = "const app=document.querySelector('#app'), prog=document.querySelector('#progress'), creditEl=document.querySelector('#credits');\nlet credits=0; const awarded=new Set(); let currentClock='';\nfunction setClock(t){currentClock=t;}\nfunction updateCredits(){}\nfunction award(key,n){if(!awarded.has(key)){awarded.add(key);credits=Math.min(100,credits+n);updateCredits();return `<div class=\\\"creditpop\\\">+${n} CREDITS</div>`}return '';}\nfunction resetCredits(){credits=0;awarded.clear();updateCredits();}\nconst panel=html=>{app.innerHTML=`<section class=\"panel\">${html}</section>`;scrollTo({top:0,behavior:'smooth'})};\nconst setP=(n,label='')=>prog.textContent=n?`Station ${n} / 7${label?' · '+label:''}`:'Start';\nconst msg=(t,g=false)=>`<div class=\"notice ${g?'good':'bad'}\">${t}</div>`;\nconst meter=(n,label)=>`<div class=\"statusline\"><b>${label}</b><span>${n} %</span></div><div class=\"bar\"><i style=\"width:${n}%\"></i></div>`;\nconst anf327=()=>`<div class=\"req stickyreq\"><b>ANF-327 – Persönliches Überweisungslimit</b><br>0–1.000 € einschließlich: ohne zusätzliche Freigabe<br>&gt;1.000–10.000 € einschließlich: zusätzliche Freigabe erforderlich<br>&gt;10.000 €: unzulässig<br>Negative Werte: unzulässig<br>Nur ganze Eurobeträge.</div>`;\nlet picks=new Set();\nfunction togglePick(prefix,i){const k=prefix+i;const el=document.getElementById(k);if(!el)return;if(picks.has(k)){picks.delete(k);el.classList.remove('selected')}else{picks.add(k);el.classList.add('selected')}}\nfunction week2(){setP(0);prog.textContent='Woche 2 · Montag';setClock('Woche 2 · Montag 08:04 Uhr');panel(`<div class=\"eyebrow\">Woche 2 · Montag 08:04 Uhr</div><h2>Unerwartete Planabweichung</h2><div class=\"notice bad\"><b>⚠ MELDUNG DES UMGEBUNGSMANAGEMENTS</b><br><br>Die Zentrale Testumgebung für Release 2.0 wurde vor Beginn der Testdurchführung geprüft. Dabei wurde ein <b>abgelaufenes SSL-Zertifikat</b> festgestellt.<br><br><b>Gute Nachricht:</b> Die vorgesehene Releasekonfiguration ist bereits installiert.<br><b>Schlechte Nachricht:</b> Das Zertifikat kann aktuell nicht erneuert werden. Der zuständige Kollege ist nicht erreichbar; die Dauer ist unklar.</div><button class=\"primary\" onclick=\"sslActions()\">Situation bewerten</button>`) }\nfunction sslActions(){prog.textContent='Woche 2 · Montag';picks.clear();let a=['Auswirkung auf die geplante Testdurchführung prüfen.','SSL-Zertifikatsprüfung umgehen und normal weitertesten.','Prüfen, welche geplanten Tätigkeiten trotz der Einschränkung sinnvoll durchgeführt werden können.','Release 2.0 aufgrund des Zertifikats sofort absagen.','Umgebungsmanagement kontaktieren und Klärung bzw. Wiederherstellung anstoßen.','Einfach warten und bis zur Behebung keinerlei weitere Aktivitäten durchführen.','Abweichung dokumentieren und Planung bei Bedarf anpassen.','Die verlorene Testzeit später als durchgeführte Testzeit dokumentieren.'];panel(`<div class=\"eyebrow\">Planabweichung</div><h2>Maßnahmen zur Störung festlegen</h2><p><b>Bis zu vier Maßnahmen auswählen.</b> Die erste bestätigte Entscheidung zählt für die Credits.</p><div class=\"options\">${a.map((x,i)=>`<button id=\"ssl${i}\" onclick=\"sslPick(${i})\">${i+1}. ${x}</button>`).join('')}</div><button onclick=\"checkSSL()\">Maßnahmen bestätigen</button><div id=\"fb\"></div>`) }\nfunction sslPick(i){let k='ssl'+i;if(picks.has(k)){picks.delete(k);document.getElementById(k).classList.remove('selected')}else if(picks.size<4){picks.add(k);document.getElementById(k).classList.add('selected')}}\nfunction checkSSL(){\n if(!picks.size){document.querySelector('#fb').innerHTML=msg('Mindestens eine Maßnahme auswählen.');return}\n let goodIds=[0,2,4,6], badIds=[1,3,5,7];\n let good=goodIds.filter(i=>picks.has('ssl'+i)).length;\n let bad=badIds.filter(i=>picks.has('ssl'+i));\n if(bad.length){\n   const questions={\n    1:'Ist es für eine kontrollierte Testdurchführung sinnvoll, eine festgestellte Sicherheitsprüfung der vorgesehenen Testumgebung zu umgehen?',\n    3:'Reicht die vorliegende Störung bereits aus, um eine Entscheidung über das gesamte Release zu treffen?',\n    5:'Werden die vorhandenen Handlungsmöglichkeiten ausreichend genutzt, wenn ausschließlich auf die Behebung gewartet wird?',\n    7:'Darf nicht durchgeführte Testzeit als tatsächlich durchgeführte Testaktivität dokumentiert werden?'\n   };\n   document.querySelector('#fb').innerHTML=`<div class=\"notice bad\"><b>Ausgewählte Maßnahmen noch einmal kritisch betrachten:</b><ul>${bad.map(i=>`<li>${questions[i]}</li>`).join('')}</ul><br>Ungeeignete Maßnahmen können wieder abgewählt und durch andere Maßnahmen ersetzt werden.</div>`;\n   return;\n }\n let score=Math.round(good*2.5), bonus=award('ssl',score);\n let summary=good===4?msg('Die Auswahl berücksichtigt die wesentlichen Handlungsmöglichkeiten der Planabweichung.',true):msg('Es wären noch weitere sinnvolle Maßnahmen auswählbar gewesen. Der gewählte Weg ist dennoch möglich. Schauen wir, welches Update das Umgebungsmanagement inzwischen hat.',true);\n document.querySelector('#fb').innerHTML=summary+bonus+`<button class=\"primary\" onclick=\"sslUpdate()\">Update des Umgebungsmanagements öffnen</button>`;\n document.querySelectorAll('#app .options button, #app button:not(.primary)').forEach(b=>b.disabled=true);\n}\n\nfunction sslUpdate(){prog.textContent='Woche 2 · Montag';setClock('Woche 2 · Montag 09:26 Uhr');panel(`<div class=\"eyebrow\">Planabweichung</div><h2>Update des Umgebungsmanagements</h2><div class=\"notice good\">✓ Das SSL-Zertifikat wurde erneuert.<br>✓ Die Zentrale Testumgebung ist wieder verfügbar.<br>✓ Die Verzögerung wurde als Planabweichung dokumentiert.</div><div class=\"story\">Die Testdurchführung kann nun beginnen.</div><button class=\"primary\" onclick=\"s4()\">Testdurchführung starten</button>`) }\nfunction s4(){setClock('Woche 2 · Montag 10:17 Uhr');setP(4,'Woche 2 · Montag');panel(`<div class=\"eyebrow\">Station 4 · Fehleranalyse</div><h2>Der gesperrte Zugang</h2><div class=\"story\">Ein Tester/Testanalyst kommt mit einem Anliegen. Bei einem Test des Logins im Kundenportal wurde ein Verhalten beobachtet, das nicht korrekt erscheint. Kann bei der Einordnung unterstützt werden?</div><div class=\"req\"><b>ANF-042 – Login im Kundenportal</b><br>Nach drei aufeinanderfolgenden falschen Passworteingaben muss das Benutzerkonto für <b>15 Minuten</b> gesperrt werden.</div><div class=\"story\"><b>Folgende Tests wurden durchgeführt:</b><br><br>Schritt 1 – Falsches Passwort → Anmeldung abgelehnt ✓<br>Schritt 2 – Falsches Passwort → Anmeldung abgelehnt ✓<br>Schritt 3 – Falsches Passwort → „Benutzerkonto gesperrt“ ✓<br>Schritt 4 – Browser aktualisiert<br>Schritt 5 – Korrektes Passwort → <b class=\"badtext\">Anmeldung erfolgreich</b></div><h3>Welche Aussage ist durch die Beobachtung gestützt?</h3><div class=\"options\"><button onclick=\"s4a(false)\">Die Sperrinformation wurde nachweislich ausschließlich im Browser gespeichert.</button><button onclick=\"s4a(true)\">Im Testobjekt befindet sich ein Fehlerzustand. Bei der Testdurchführung zeigt sich eine Fehlerwirkung.</button><button onclick=\"s4a(false)\">Die konkrete Fehlhandlung in der Entwicklung ist damit nachgewiesen.</button></div><div id=\"fb\"></div>`) }\n\nfunction s4a(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ Korrekt – Der Tester/Testanalyst hat eine Fehlerwirkung entdeckt. Diese muss nun über eine Fehlermeldung an die Entwicklung weitergegeben werden.',true)+`<button class=\"primary\" onclick=\"s4ideas()\">Weiter</button>`:msg('Aus der sichtbaren Fehlerwirkung lässt sich keine konkrete Fehlhandlung sicher ableiten.')}\n\nfunction s4ideas(){picks.clear();let a=['Schriftgröße der Fehlermeldung überprüfen','Sperre nach Schließen und erneutem Öffnen des Browsers prüfen','Profilbild ändern','Anmeldung nach Ablauf der 15 Minuten prüfen','Rechtschreibung im Impressum prüfen','Sperre in einer zweiten Sitzung prüfen','Farbe der Schaltfläche „Anmelden“ prüfen','Anmeldung unmittelbar vor Ablauf der Sperrzeit prüfen'];panel(`<div class=\"eyebrow\">Station 4 · Weitere Testfälle</div><h2>Weitere Testfälle</h2><div class=\"story\">Welche weiteren Tests könnten zur Untersuchung des beobachteten Verhaltens sinnvoll sein?</div><div class=\"req\"><b>ANF-042 – Login im Kundenportal</b><br>Nach drei aufeinanderfolgenden falschen Passworteingaben muss das Benutzerkonto für 15 Minuten gesperrt werden.</div><div class=\"options\">${a.map((x,i)=>`<button id=\"i${i}\" onclick=\"togglePick('i',${i})\">${i+1}. ${x}</button>`).join('')}</div><button onclick=\"checkIdeas()\">Auswahl prüfen</button><div id=\"fb\"></div>`) }\n\nfunction codeFound(code,nextFn,nextLabel,station){panel(`<div class=\"creditpop\">+5 CREDITS</div><div class=\"eyebrow\">${station} · Abschluss</div><h2>Code gefunden</h2><div class=\"foundcode\">${code}</div><div class=\"story center\"><b>Dieser Code wird später noch benötigt.</b><br>Am besten notieren.</div><button class=\"primary\" onclick=\"${nextFn}()\">${nextLabel}</button>`)}\nfunction checkIdeas(){let need=[1,3,5,7],good=need.filter(i=>picks.has('i'+i)).length,bad=[0,2,4,6].filter(i=>picks.has('i'+i)).length;if(good>=2&&bad===0){let c=good===4?5:3;let bonus=award('s4ideas',c);document.querySelector('#fb').innerHTML=bonus+msg(good===4?'✓ Richtig – die relevanten weiteren Testfälle wurden erkannt.':'✓ Richtig – weitere sinnvolle Testfälle wären möglich gewesen.',true)+`<button class=\"primary\" onclick=\"show1459()\">Weiter</button>`}else document.querySelector('#fb').innerHTML=msg('Die ausgewählten Testfälle sollten sich unmittelbar auf Dauer und Beständigkeit der Kontosperre beziehen.')}\nfunction show1459(){award('s4',5);codeFound('1459','s5','Dienstag öffnen','Station 4')}\n\nfunction s5(){setClock('Woche 2 · Dienstag 09:08 Uhr');setP(5,'Woche 2 · Dienstag');panel(`<div class=\"eyebrow\">Station 5 · Fehlermeldung</div><h2>Fehlermeldung</h2><div class=\"mail\"><b>VON:</b> Entwicklung<br><b>BETREFF:</b> FM-481 – Überweisungsvorlage kann nicht gespeichert werden<br><br>„Nicht nachvollziehbar. Die Vorlage konnte im Test erfolgreich angelegt werden. Welche Daten wurden eingegeben?“</div><div class=\"notice bad\">⚠ FM-481 · INFORMATIONEN UNVOLLSTÄNDIG</div><button class=\"primary\" onclick=\"s5report()\">Fehlermeldung prüfen</button>`) }\n\nfunction s5report(){picks.clear();panel(`<div class=\"eyebrow\">Station 5 · Fehlermeldung prüfen</div><h2>FM-481 – Überweisungsvorlage kann nicht gespeichert werden</h2><div class=\"file\"><b>Testdatum:</b> Dienstag, Woche 2<br><br><b>Schritte</b><br>1. Überweisungen öffnen · 2. „Neue Vorlage“ · 3. Daten eingeben · 4. „Speichern“<br><br><b>Erwartet:</b> Vorlage wird gespeichert.<br><b>Tatsächlich:</b> „Die eingegebenen Daten konnten nicht verarbeitet werden.“</div><h3>Welche zwei Informationen helfen hier besonders bei Analyse und Reproduktion?</h3><div class=\"options\"><button id=\"f0\" onclick=\"togglePick('f',0)\">Name der testenden Person</button><button id=\"f1\" onclick=\"togglePick('f',1)\">Verwendete Eingabedaten</button><button id=\"f2\" onclick=\"togglePick('f',2)\">Bildschirmfotos der Testdurchführung</button><button id=\"f3\" onclick=\"togglePick('f',3)\">Farbe der Schaltfläche</button><button id=\"f4\" onclick=\"togglePick('f',4)\">Vermutung zum fehlerhaften Programmcode</button></div><button onclick=\"checkReport()\">Weiter</button><div id=\"fb\"></div>`) }\n\nfunction checkReport(){let ok=picks.has('f1')&&picks.has('f2')&&picks.size===2;document.querySelector('#fb').innerHTML=ok?msg('✓ FEHLERMELDUNG ERGÄNZT',true)+`<button class=\"primary\" onclick=\"s5shot()\">Weiter</button>`:msg('Gesucht sind Informationen, mit denen die dokumentierte Situation möglichst genau nachvollzogen werden kann.')}\n\nfunction s5shot(){panel(`<div class=\"eyebrow\">Station 5 · Reproduktion und Analyse</div><h2>Bildschirmfoto der Testdurchführung</h2><div class=\"story\">Kann erkannt werden, warum es nicht funktioniert hat? Das Bildschirmfoto genau betrachten.</div><div class=\"screen\"><b>Neue Überweisungsvorlage</b><br><br>Empfänger<input value=\"Müller & Söhne GmbH\" readonly>IBAN<input value=\"DE12 3456 7890 1234 5678 00\" readonly>Vorlagenname / Verwendungszweck<input value=\"Büromiete September\" readonly><div class=\"error\">Die eingegebenen Daten konnten nicht verarbeitet werden.</div><p class=\"small\" style=\"text-align:right\">Uhrzeit: <b>17:27</b></p></div><h3>Wie sollte die Situation zunächst reproduziert werden?</h3><div class=\"options\"><button onclick=\"repro(true)\">Mit exakt den dokumentierten Eingabedaten</button><button onclick=\"repro(false)\">Mit beliebigen gültigen Testdaten</button><button onclick=\"repro(false)\">Nur den Empfängernamen ändern</button></div><div id=\"fb\"></div>`) }\n\nfunction repro(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ REPRODUKTION ERFOLGREICH · Mit den dokumentierten Daten tritt die Fehlerwirkung erneut auf.',true)+`<button class=\"primary\" onclick=\"s5chars()\">Eingabedaten untersuchen</button>`:msg('Zunächst sollten die dokumentierten Bedingungen möglichst genau nachgestellt werden.')}\nfunction s5chars(){panel(`<div class=\"eyebrow\">Station 5 · Reproduktion und Analyse</div><h2>Zulässige Zeichen – Empfängername</h2><div class=\"req\">Erlaubt: A–Z · a–z · 0–9 · Leerzeichen · . , - / &</div><div class=\"screen\"><b>Neue Überweisungsvorlage</b><br><br>Empfänger<input value=\"Müller & Söhne GmbH\" readonly>IBAN<input value=\"DE12 3456 7890 1234 5678 00\" readonly>Vorlagenname / Verwendungszweck<input value=\"Büromiete September\" readonly><div class=\"error\">Die eingegebenen Daten konnten nicht verarbeitet werden.</div><p class=\"small\" style=\"text-align:right\">Uhrzeit: <b>17:27</b></p></div><h3>Warum hat die Überweisung nicht geklappt?</h3><div class=\"options\"><button onclick=\"chars(false)\">Das Zeichen & ist nicht zulässig.</button><button onclick=\"chars(true)\">Der Empfängername enthält Umlaute.</button><button onclick=\"chars(false)\">Alle verwendeten Zeichen sind laut Vorgabe zulässig.</button></div><div id=\"fb\"></div>`) }\n\nfunction chars(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ Analyse abgeschlossen – es handelt sich nicht um eine Fehlerwirkung. Das System hat gemäß Vorgabe reagiert. Die Eingabe entsprach nicht den zulässigen Zeichen für den Empfängernamen.',true)+`<div class=\"req\"><b>Ergebnis</b><br>Müller & Söhne GmbH → Eingabe wird abgewiesen<br>Mueller & Soehne GmbH → Vorlage erfolgreich gespeichert</div><button class=\"primary\" onclick=\"show1727()\">Weiter</button>`:msg('Die zulässigen Zeichen mit dem Empfängernamen im Bildschirmfoto vergleichen.')}\nfunction show1727(){codeFound('1727','s6','Donnerstag öffnen','Station 5')}\n\nfunction s6(){setClock('Woche 2 · Donnerstag 13:15 Uhr');award('s5',10);setP(6,'Woche 2 · Donnerstag');panel(`<div class=\"eyebrow\">Station 6 · Teststeuerung</div><h2>Die letzten 12 Stunden</h2><div class=\"story\">Es sind nur noch wenige Stunden bis zum Testende. Einige Tests müssen noch durchgeführt werden. Es verbleiben <b>12 Stunden</b> Testkapazität und <b>5 Themengebiete</b> müssen betrachtet werden.<br><br>Es muss abgewogen werden, was noch getestet werden kann und was nicht. Eine Grundlage dafür ist das <b>Produktrisiko</b>.<br><br><b>Doch was ist das?</b></div><div class=\"req\"><b>PRODUKTRISIKO</b><br>[ ? ] × [ ? ]</div><div class=\"options\"><button onclick=\"risk(false)\">Testfallanzahl × Entwicklungsdauer</button><button onclick=\"risk(false)\">Testeranzahl × Testdauer</button><button onclick=\"risk(true)\">Eintrittswahrscheinlichkeit × Schadensausmaß</button><button onclick=\"risk(false)\">Anzahl Änderungen × Anzahl Testfälle</button></div><div id=\"fb\"></div>`) }\n\nfunction risk(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ Korrekt – Wie wahrscheinlich ist der Eintritt und welches Schadensausmaß entsteht, wenn das Risiko eintritt?',true)+`<button class=\"primary\" onclick=\"s6matrix()\">Weiter</button>`:msg('Produktrisiko betrachtet die Wahrscheinlichkeit und das mögliche Schadensausmaß.')}\n\nfunction s6matrix(){panel(`<div class=\"eyebrow\">Station 6 · Risikobewertung</div><h2>Risikobewertung</h2><div class=\"cards\"><div class=\"card\"><h4>Überweisungen</h4>Hoher Änderungsumfang; falsche Beträge/Empfänger/Freigaben möglich.<br><br><b>TF-327-04</b>: 1.001 € – fehlgeschlagen.</div><div class=\"card\"><h4>Persönliche Daten</h4>Mehrere Komponenten geändert; Daten können für Freigaben und Sicherheitsinformationen relevant sein.</div><div class=\"card\"><h4>Umsatzsuche</h4>Suche geändert; falsche Filter oder fehlende Umsätze möglich.<br><br><b>TF-US-18</b>: Filterkombination liefert unvollständige Trefferliste – <span class=\"badtext\">FEHLGESCHLAGEN</span>.</div><div class=\"card\"><h4>Elektronisches Postfach</h4>Begrenzte Änderung; neue Dokumente könnten vorübergehend nicht angezeigt werden.</div><div class=\"card\"><h4>Profilbild</h4>Neue Funktion; Bild kann fehlen oder falsch dargestellt werden.</div></div><h3>Welche beiden Bereiche gehören nach diesen Angaben in hoch / hoch?</h3><div class=\"options\"><button onclick=\"matrix(false)\">Profilbild + Elektronisches Postfach</button><button onclick=\"matrix(false)\">Umsatzsuche + Profilbild</button><button onclick=\"matrix(false)\">Umsatzsuche + Elektronisches Postfach</button><button onclick=\"matrix(false)\">Persönliche Daten + Profilbild</button><button onclick=\"matrix(true)\">Überweisungen + Persönliche Daten</button></div><div id=\"fb\"></div>`) }\n\nfunction matrix(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ Richtig – die beiden risikoreichsten Bereiche sind Überweisungen und Persönliche Daten.',true)+`<button class=\"primary\" onclick=\"s6plan()\">Weiter</button>`:msg('Eintrittswahrscheinlichkeit, Schadensausmaß und bisherige Testergebnisse gemeinsam berücksichtigen.')}\n\nfunction s6plan(){panel(`<div class=\"eyebrow\">Station 6 · Replanung</div><h2>Replanung</h2><div class=\"story\">Es bleibt nicht mehr genug Zeit, um alle Themen vollständig zu testen. Eine Replanung ist erforderlich: Welche Bereiche sollen Henry, Lilia und Georg in den letzten Stunden bearbeiten?</div><div class=\"cards\"><div class=\"card\"><h4>Henry</h4>4 h</div><div class=\"card\"><h4>Lilia</h4>4 h</div><div class=\"card\"><h4>Georg</h4>4 h</div></div>${['Henry','Lilia','Georg'].map((n,i)=>`<div class=\"req\"><b>${n} – 4 h</b><br><select id=\"p${i}\"><option value=\"\">– Bereich –</option><option>Überweisungen</option><option>Persönliche Daten</option><option>Umsatzsuche</option><option>Elektronisches Postfach</option><option>Profilbild</option></select></div>`).join('')}<button onclick=\"checkPlan()\">Replanung speichern</button><div id=\"fb\"></div>`) }\n\nfunction checkPlan(){let a=[p0.value,p1.value,p2.value],hi=a.filter(x=>x==='Überweisungen'||x==='Persönliche Daten').length;document.querySelector('#fb').innerHTML=a.every(Boolean)&&hi>=2?msg('✓ 12 STUNDEN RISIKOORIENTIERT EINGEPLANT',true)+`<button class=\"primary\" onclick=\"s6sick()\">Plan speichern</button>`:msg('Bitte die Entscheidung noch einmal prüfen. Bereiche mit hohem Produktrisiko sollen deutlich berücksichtigt werden.')}\n\nlet henryDecision='';\nfunction s6sick(){setClock('Woche 2 · Donnerstag 13:42 Uhr');henryDecision='';panel(`<div class=\"eyebrow\">Station 6 · Ressourcenabweichung</div><h2>Neue E-Mail</h2><div class=\"mail\"><b>VON:</b> Henry<br><b>BETREFF:</b> Ausfall für den Rest der Testphase<br><br>Hallo,<br><br>ich muss mich leider für den Rest der Testphase krankmelden.<br><br>Viele Grüße<br>Henry</div><div class=\"notice danger\"><b>⚠ RESSOURCENABWEICHUNG</b><br>Geplante Kapazität: 12 h · Noch verfügbar: 8 h<br>Henry: NICHT VERFÜGBAR</div><h3>Wie soll reagiert werden?</h3><div class=\"options\"><button id=\"decA\" onclick=\"selectHenryDecision('A')\">Verlust ignorieren; Plan unverändert lassen</button><button id=\"decB\" onclick=\"selectHenryDecision('B')\">Kapazität neu verteilen und risikoorientiert priorisieren</button><button id=\"decC\" onclick=\"selectHenryDecision('C')\">Projektleitung informieren und Ersatzkapazität prüfen</button><button id=\"decD\" onclick=\"selectHenryDecision('D')\">Release sofort stoppen</button></div><button onclick=\"confirmHenryDecision()\">Entscheidung bestätigen</button><div id=\"fb\"></div>`) }\nfunction selectHenryDecision(x){henryDecision=x;document.querySelectorAll('[id^=dec]').forEach(b=>b.classList.remove('selected'));document.querySelector('#dec'+x)?.classList.add('selected');document.querySelector('#fb').innerHTML=''}\nfunction confirmHenryDecision(){let f=document.querySelector('#fb');if(!henryDecision){f.innerHTML=msg('Bitte zunächst eine Antwort auswählen.');return}if(henryDecision==='B'){f.innerHTML=award('henryB',5)+msg('✓ Kapazität wird risikoorientiert neu verteilt. Die Auswirkungen werden anschließend dokumentiert.',true)+`<button class=\"primary\" onclick=\"s6status()\">Weiter</button>`}else if(henryDecision==='C'){f.innerHTML=award('henryC',2)+msg('✓ Projektleitung informiert. Ersatzkapazität ist nicht verfügbar; die verbleibende Kapazität muss nun risikoorientiert neu verteilt werden.',true)+`<button class=\"primary\" onclick=\"s6status()\">Weiter</button>`}else f.innerHTML=msg('Neuer Versuch – kann das stimmen?')}\n\nfunction s6status(){setClock('Woche 2 · Donnerstag 17:28 Uhr');panel(`<div class=\"eyebrow\">Station 6 · Teststatus</div><h2>Teststatus – Auswirkungen dokumentieren</h2><div class=\"story\">Für Freitag wird ein transparenter Überblick über nicht durchgeführte Tests und verbleibende Produktrisiken benötigt.</div><h3>Testfallportfolio</h3><select id=\"st1\"><option value=\"\">– wählen –</option><option>Alle geplanten Tests wurden durchgeführt.</option><option value=\"p\">Geplante Tests konnten teilweise nicht durchgeführt werden.</option><option>Nur fehlgeschlagene Tests werden dokumentiert.</option><option>Nicht durchgeführte Tests werden als blockiert gewertet.</option></select><h3>Produktrisiko</h3><select id=\"st2\"><option value=\"\">– wählen –</option><option>Ist automatisch gesunken.</option><option value=\"r\">Muss unter Berücksichtigung der nicht durchgeführten Tests erneut betrachtet werden.</option><option>Spielt nach der Replanung keine Rolle mehr.</option><option>Wird nur bei fehlgeschlagenen Tests dokumentiert.</option></select><h3>Testabschluss</h3><select id=\"st3\"><option value=\"\">– wählen –</option><option>Nicht durchgeführte Tests aus dem Bericht entfernen.</option><option value=\"t\">Nicht durchgeführte Tests und daraus verbleibende Unsicherheiten transparent dokumentieren.</option><option>Nur erfolgreiche Testfälle in den Abschluss übernehmen.</option><option>Alle offenen Punkte automatisch als behoben markieren.</option></select><br><br><button onclick=\"statusCheck()\">Teststatus aktualisieren</button><div id=\"fb\"></div>`) }\n\nfunction statusCheck(){let ok=st1.value==='p'&&st2.value==='r'&&st3.value==='t';document.querySelector('#fb').innerHTML=ok?msg('✓ TESTSTATUS AKTUALISIERT · Ressourcenausfall dokumentiert · Planung angepasst · nicht durchgeführte Tests gekennzeichnet · Produktrisiken zur Neubewertung vorgemerkt',true)+`<button class=\"primary\" onclick=\"s7()\">Endspurt</button>`:msg('Der Status muss Ressourcenausfall, nicht durchgeführte Tests und verbleibende Unsicherheit transparent abbilden.')}\n\nfunction s7(){setClock('Woche 2 · Freitag 09:03 Uhr');award('s6',10);setP(7,'Woche 2 · Freitag');panel(`<div class=\"eyebrow\">Station 7 · Testabschluss</div><h2>Der Testabschluss</h2>${meter(18,'TESTABSCHLUSSBERICHT VOLLSTÄNDIG')}<div class=\"notice bad\">⚠ TESTABSCHLUSS UNVOLLSTÄNDIG · Einige Daten fehlen, andere widersprechen dem Testverlauf.</div><div class=\"split\"><div class=\"file\"><b>TESTKONZEPT</b><br>Testobjekt ✓<br>Zeitraum ✓<br>Testziele ✓<br>Testumfang ✓<br>Zentrale Testumgebung ✓<br>Henry · Lilia · Georg ✓</div><div class=\"file\"><b>ABSCHLUSSBERICHT</b><br>Testdurchführung [BESCHÄDIGT]<br>Testergebnisse [BESCHÄDIGT]<br>Fehlermeldungen [BESCHÄDIGT]<br>Planabweichungen [BESCHÄDIGT]<br>Produktrisiken [BESCHÄDIGT]<br>Testziele [BESCHÄDIGT]<br>Empfehlung [FEHLT]</div></div><button class=\"primary\" onclick=\"s7numbers()\">Bericht rekonstruieren</button>`)}\nfunction s7numbers(){panel(`<div class=\"eyebrow\">Station 7 · Testdurchführung</div><h2>Wie viele Testfälle wurden durchgeführt?</h2><table><tr><td>Geplante Testfälle</td><td>240</td></tr><tr><td>Erfolgreich durchgeführt</td><td>144</td></tr><tr><td>Fehlgeschlagen</td><td>36</td></tr><tr><td>Blockiert</td><td>12</td></tr><tr><td>Nicht durchgeführt</td><td>48</td></tr></table><p>Tatsächlich durchgeführt: <input id=\"fn\" type=\"number\"> · Anteil: <input id=\"fp\" type=\"number\"> %</p><button onclick=\"numbers()\">Prüfen</button><div id=\"fb\"></div>`) }\n\nfunction numbers(){let ok=+fn.value===180&&+fp.value===75;document.querySelector('#fb').innerHTML=ok?msg('✓ 180 von 240 geplanten Testfällen wurden durchgeführt = 75 %. 12 blockiert, 48 nicht durchgeführt.',true)+meter(31,'TESTABSCHLUSSBERICHT VOLLSTÄNDIG')+`<button class=\"primary\" onclick=\"s7evidence()\">Ergebnisarchiv öffnen</button>`:msg('Blockierte und nicht durchgeführte Testfälle zählen hier nicht als durchgeführt.')}\nfunction s7evidence(){panel(`<div class=\"eyebrow\">Station 7 · Fehlersituation und Risiken</div><h2>Fehlersituation</h2><div class=\"cards\"><div class=\"card\"><h4>FM-472</h4>Kontosperre nach Browseraktualisierung aufgehoben.<br><b>Schweregrad: hoch</b></div><div class=\"card\"><h4>FM-486</h4>Zusätzliche Freigabe bei 1.001 € nicht angefordert.<br><b>Schweregrad: hoch</b></div><div class=\"card\"><h4>FM-481</h4>Überweisungsvorlage kann nicht gespeichert werden.<br><b>Schweregrad: niedrig</b><br>Analyse: Systemverhalten entspricht der Vorgabe.</div></div><h3>Welche Risiken können im Abschlussbericht aufgenommen werden?</h3><div class=\"options\"><button onclick=\"evidence('A')\">Es bestehen keine verbleibenden Produktrisiken.</button><button onclick=\"evidence('C')\">Alle festgestellten Situationen sind behoben, weil sie dokumentiert wurden.</button><button onclick=\"evidence('D')\">Release 2.0 wurde als fehlerfrei nachgewiesen.</button><button onclick=\"evidence('E')\">Die analysierte FM-481 muss als schwerwiegender Produktfehler bewertet werden.</button><button onclick=\"evidence('B')\">Nicht alle geplanten Tests konnten durchgeführt werden; hoch bewertete Fehlersituationen und nicht durchgeführte Tests lassen verbleibende Produktrisiken und Unsicherheit bestehen.</button></div><div id=\"fb\"></div>`) }\n\nfunction evidence(x){document.querySelector('#fb').innerHTML=x==='B'?msg('✓ Risiken korrekt erkannt und benannt.',true)+meter(59,'TESTABSCHLUSSBERICHT VOLLSTÄNDIG')+`<button class=\"primary\" onclick=\"s7goals()\">Freigabebewertung</button>`:msg('Diese Aussage wird durch die vorliegenden Testinformationen nicht gestützt.')}\n\nfunction s7plan(){panel(`<div class=\"eyebrow\">Station 7 · Plan / Ist</div><h2>Abweichungen dokumentieren</h2><div class=\"req\">Geplant: 3 Tester (Henry, Lilia, Georg)<br><b>Tatsächlich:</b> Henry fiel während der verbleibenden Testphase aus.</div><div class=\"req\">Geplant: Testüberwachung und Teststeuerung<br><b>Tatsächlich:</b> Planung wurde aufgrund des Ressourcenausfalls angepasst.</div><div class=\"req\">Geplant: Zentrale Testumgebung<br><b>Tatsächlich:</b> Testdurchführung in der vorgesehenen Umgebung.</div>${meter(59,'TESTABSCHLUSSBERICHT VOLLSTÄNDIG')}<button class=\"primary\" onclick=\"s7goals()\">Testziele bewerten</button>`)}\nfunction s7goals(){panel(`<div class=\"eyebrow\">Station 7 · Testziele</div><h2>Testziele bewerten</h2><div class=\"file\">Informationen über Qualität gewinnen · Anforderungen prüfen · Fehlerzustände/Fehlerwirkungen aufdecken · Informationen für Entscheidungen bereitstellen</div><div class=\"options\"><button onclick=\"goals(false)\">Alle Testziele vollständig erreicht, weil 75 % durchgeführt wurden.</button><button onclick=\"goals(false)\">Kein Testziel erreicht, weil nicht alle Tests durchgeführt wurden.</button><button onclick=\"goals(true)\">Die Tests lieferten Qualitätsinformationen und deckten Fehlerwirkungen auf; nicht durchgeführte und blockierte Tests lassen verbleibende Unsicherheit.</button></div><div id=\"fb\"></div>`)}\nfunction goals(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ TESTZIELE BEWERTET',true)+meter(72,'TESTABSCHLUSSBERICHT VOLLSTÄNDIG')+`<button class=\"primary\" onclick=\"s7risk()\">Produktrisiken prüfen</button>`:msg('Der Durchführungsgrad ist nicht identisch mit der Zielerreichung.')}\nfunction s7risk(){panel(`<div class=\"eyebrow\">Station 7 · Produktrisiken</div><h2>Verbleibende Produktrisiken prüfen</h2><div class=\"file\"><b>Gespeicherter Status:</b> „KEINE“</div><div class=\"notice bad\">⚠ WIDERSPRUCH ZU TESTERGEBNISSEN</div><div class=\"options\"><button onclick=\"finalrisk(false)\">Keine verbleibenden Produktrisiken.</button><button onclick=\"finalrisk(true)\">Verbleibende Produktrisiken vorhanden; besonders bei Überweisungen bestehen wegen Abweichungen und nicht vollständig durchgeführter Tests Unsicherheiten.</button></div><div id=\"fb\"></div>`)}\nfunction finalrisk(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ VERBLEIBENDE PRODUKTRISIKEN DOKUMENTIERT',true)+meter(86,'TESTABSCHLUSSBERICHT VOLLSTÄNDIG')+`<button class=\"primary\" onclick=\"s7rec()\">Empfehlung formulieren</button>`:msg('Festgestellte Abweichungen und nicht durchgeführte Tests lassen verbleibende Unsicherheit bestehen.')}\nfunction s7rec(){panel(`<div class=\"eyebrow\">Station 7 · Freigabeempfehlung</div><h2>Freigabeempfehlung formulieren</h2><div class=\"options\"><button onclick=\"rec(false)\">Release 2.0 kann ohne Einschränkungen produktiv gesetzt werden.</button><button onclick=\"rec(false)\">Release 2.0 darf nicht produktiv gesetzt werden, weil nicht alle Tests durchgeführt wurden.</button><button onclick=\"rec(true)\">Vor der Produktivsetzung sollten besonders die verbleibenden Unsicherheiten bei Überweisungen berücksichtigt werden. Ausstehende risikorelevante Tests sollten nach Möglichkeit nachgeholt bzw. das verbleibende Produktrisiko vor der Release-Entscheidung ausdrücklich bewertet werden.</button></div><div id=\"fb\"></div>`)}\nfunction rec(ok){document.querySelector('#fb').innerHTML=ok?msg('✓ EMPFEHLUNG DER TESTLEITUNG FORMULIERT',true)+meter(100,'TESTABSCHLUSSBERICHT VOLLSTÄNDIG')+`<div class=\"notice good\">✓ Testergebnisse zusammengefasst<br>✓ Abweichungen dokumentiert<br>✓ Testziele bewertet<br>✓ Verbleibende Produktrisiken dargestellt<br>✓ Empfehlung formuliert</div><button class=\"primary\" onclick=\"finish()\">Abschlussbericht übermitteln</button>`:msg('Die Testleitung liefert eine begründete Entscheidungsgrundlage; sie trifft hier nicht selbst die Release-Entscheidung.')}\nfunction finish(){setClock('Woche 2 · Freitag 15:58 Uhr');award('s7',20);panel(`<div class=\"eyebrow\">Woche 2 · Freitag 15:58 Uhr</div><h1>Release 2.0</h1><h2>Testphase abgeschlossen</h2><div class=\"story mono\">testabschluss_release20.pdf wird erzeugt …<br>Ergebnisse und verbleibende Risiken dokumentiert ✓<br>Freigabeempfehlung übermittelt ✓<br><span class=\"goodtext\">✓ ERFOLGREICH</span></div><div class=\"notice\"><b>ENTSCHEIDUNG ÜBER PRODUKTIVSETZUNG</b><br><br>Um die Entscheidung, ob das Release gerettet werden konnte, einsehen zu können, gibt es noch zwei letzte Rätsel zu lösen.</div><button class=\"primary\" onclick=\"finalCodes()\">Rätsel lösen</button>`)}\nfunction finalCodes(){panel(`<div class=\"eyebrow\">Abschlussrätsel · 1 von 2</div><h2>Fundcodes eingeben</h2><p>Die drei während des Spiels gefundenen Codes eingeben.</p><div class=\"grid3\"><div class=\"bucket\"><input id=\"fc1\" class=\"code\" maxlength=\"4\" inputmode=\"numeric\" placeholder=\"____\"></div><div class=\"bucket\"><input id=\"fc2\" class=\"code\" maxlength=\"4\" inputmode=\"numeric\" placeholder=\"____\"></div><div class=\"bucket\"><input id=\"fc3\" class=\"code\" maxlength=\"4\" inputmode=\"numeric\" placeholder=\"____\"></div></div><br><button onclick=\"checkFinalCodes()\">Codes prüfen</button><div id=\"fb\"></div>`)}\nfunction checkFinalCodes(){let ok=fc1.value==='1459'&&fc2.value==='1727'&&fc3.value==='8306';document.querySelector('#fb').innerHTML=ok?msg('✓ Die Kombination stimmt.',true)+`<button class=\"primary\" onclick=\"phoneRiddle()\">Letztes Rätsel</button>`:msg('Die Kombination stimmt noch nicht.')}\nlet hintLevel=0, phoneCode='';\nfunction phoneRiddle(){\n hintLevel=0;phoneCode='';\n panel(`<div class=\"eyebrow\">Abschlussrätsel · 2 von 2</div>\n <div class=\"story\">Gesucht wird ein Code, der gleichzeitig ein Wort ergibt. Hierum ging es die letzten beiden Wochen.</div>\n <div class=\"oldphone\">\n   <div class=\"speaker\"></div>\n   <div class=\"phonescreen\"><span>16:00</span><small id=\"phoneEntry\">_ _ _ _</small></div>\n   <div class=\"phonebrand\">MOBILE</div>\n   <div class=\"phonecontrols\"><button class=\"callkey green\" aria-label=\"Anrufen\">☎</button><button class=\"navkey\" aria-label=\"Navigation\">●</button><button class=\"callkey red\" aria-label=\"Auflegen\">☎</button></div>\n   <div class=\"phonekeys\">\n    <button onclick=\"phonePress('1')\"><b>1</b><small>&nbsp;</small></button>\n    <button onclick=\"phonePress('2')\"><b>2</b><small>ABC</small></button>\n    <button onclick=\"phonePress('3')\"><b>3</b><small>DEF</small></button>\n    <button onclick=\"phonePress('4')\"><b>4</b><small>GHI</small></button>\n    <button onclick=\"phonePress('5')\"><b>5</b><small>JKL</small></button>\n    <button onclick=\"phonePress('6')\"><b>6</b><small>MNO</small></button>\n    <button onclick=\"phonePress('7')\"><b>7</b><small>PQRS</small></button>\n    <button onclick=\"phonePress('8')\"><b>8</b><small>TUV</small></button>\n    <button onclick=\"phonePress('9')\"><b>9</b><small>WXYZ</small></button>\n    <button onclick=\"phoneClear()\"><b>⌫</b><small>LÖSCHEN</small></button>\n    <button onclick=\"phonePress('0')\"><b>0</b><small>+</small></button>\n    <button onclick=\"checkPhoneRiddle()\"><b>✓</b><small>PRÜFEN</small></button>\n   </div>\n </div>\n <div class=\"riddleactions\"><button id=\"hintBtn\" onclick=\"showHint()\">Tipp</button></div><div id=\"hintbox\"></div><div id=\"fb\"></div>`)\n}\nfunction renderPhoneCode(){const el=document.querySelector('#phoneEntry');if(el)el.textContent=(phoneCode+'____').slice(0,4).split('').join(' ')}\nfunction phonePress(n){if(phoneCode.length<4){phoneCode+=n;renderPhoneCode();document.querySelector('#fb').innerHTML=''}}\nfunction phoneClear(){phoneCode=phoneCode.slice(0,-1);renderPhoneCode();document.querySelector('#fb').innerHTML=''}\nfunction showHint(){hintLevel=Math.min(3,hintLevel+1);const hints=[`8306, 1459 und 1727 – die Zahlen, die gesucht werden, befinden sich in zwei der drei Codes.`,`Es sind 8306 und 1727 – und eine Zahl ist doppelt.`,`Der Lösungscode bzw. das Lösungswort beginnt mit den ersten beiden Zahlen analog einer der beiden Codes.`];document.querySelector('#hintbox').innerHTML=msg(`<b>Tipp ${hintLevel} von 3</b><br>${hints[hintLevel-1]}`,true);document.querySelector('#hintBtn').textContent=hintLevel<3?'Nächster Tipp':'Tipp 3 / 3';if(hintLevel===3)document.querySelector('#hintBtn').disabled=true}\nfunction checkPhoneRiddle(){if(phoneCode==='8378'){releaseDecision()}else{document.querySelector('#fb').innerHTML=msg('Der Code stimmt noch nicht.')}}\nfunction releaseDecision(){panel(`<div class=\"eyebrow\">Release-Entscheidung</div><div class=\"notice good\"><b>ENTSCHEIDUNG DER RELEASE-VERANTWORTLICHEN</b><br><br>Die Freigabeempfehlungen wurden eingeholt und unter Berücksichtigung der dokumentierten Einschränkungen bewertet.</div><div class=\"bigstatus center\">RELEASE STATUS<br>RELEASE 2.0 FREIGEGEBEN<br><small>Produktivsetzung erfolgt · Gesammelte Credits: ${credits} / 100</small></div><div class=\"story center\"><b>GESCHAFFT!</b><br>Release 2.0 ist gerettet.<br>Danke für die Unterstützung!</div><br><button onclick=\"parent.restartGame()\">Spiel neu starten</button>`)}\n\n\nfunction startWeek2QS(){\n  currentClock=''; awarded.clear(); credits=45; updateCredits();\n  prog.textContent='Woche 2 · Montag';\n  week2();\n}\n\nstartWeek2QS();\n";
